import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is rustpad-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1787092618000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-rustpad-mcp" tabindex="-1">What is rustpad-mcp? <a class="header-anchor" href="#what-is-rustpad-mcp" aria-label="Permalink to “What is rustpad-mcp?”">​</a></h1><p>rustpad-mcp is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server for <a href="https://github.com/ekzhang/rustpad" target="_blank" rel="noreferrer">Rustpad</a>, the efficient, minimal, self-hosted collaborative text editor. It lets an AI assistant read pads, create them, append to them, search-and-replace inside them, and set their editor language — against your own instance.</p><h2 id="why-it-exists" tabindex="-1">Why it exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to “Why it exists”">​</a></h2><p>Rustpad&#39;s HTTP surface is read-only: <code>GET /api/text/{id}</code> and <code>GET /api/stats</code>. Everything that changes a pad happens over a WebSocket speaking an operational-transformation (OT) protocol. rustpad-mcp implements enough of that protocol to act as a well-behaved client:</p><ul><li><strong>Edits are operations, not overwrites.</strong> <code>append_to_document</code> and <code>replace_in_document</code> retain every character they do not touch. If a human is typing in the same pad at the same moment, the Rustpad server transforms the two edits against each other and both land.</li><li><strong>Positions are Unicode code points.</strong> Rustpad counts characters the way Rust does, not the way JavaScript strings do — the server gets this right, emoji and all, and rejects text that cannot survive the trip (unpaired surrogates).</li><li><strong>The model is a visible collaborator.</strong> While editing, the server announces itself as <code>rustpad-mcp</code>, so anyone with the pad open sees who is typing.</li></ul><h2 id="what-rustpad-is-—-and-is-not" tabindex="-1">What Rustpad is — and is not <a class="header-anchor" href="#what-rustpad-is-—-and-is-not" aria-label="Permalink to “What Rustpad is — and is not”">​</a></h2><p>Two properties of Rustpad shape everything this server does:</p><ul><li><strong>Pads are ephemeral.</strong> Documents live in the Rustpad server&#39;s memory and are lost on restart and after 24 hours without an open connection (unless the instance runs with <code>SQLITE_URI</code> persistence). The tools say so in their results; treat pads as shared scratch space, not storage.</li><li><strong>There is no authentication.</strong> Anyone who can reach the instance and knows a pad id can read and write it. That makes every pad untrusted input — see <a href="/guide/security">Security</a> for what the server does about it.</li></ul><h2 id="the-tool-set" tabindex="-1">The tool set <a class="header-anchor" href="#the-tool-set" aria-label="Permalink to “The tool set”">​</a></h2><p>Eight tools: three read (<code>get_document</code>, <code>get_document_info</code>, <code>get_stats</code>) and five write (<code>create_document</code>, <code>set_document</code>, <code>append_to_document</code>, <code>replace_in_document</code>, <code>set_language</code>). The full list with parameters is in the <a href="/reference/tools">tools reference</a>.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};